import {meanings,words,glyph,chapters,evidence,checkTranslation} from './rules.js';
const $=s=>document.querySelector(s);let chapter=0,site=0,solved=false,finished=false,guesses={},confirmed=new Set(),seen=new Set([0]);
const diagramIcons={vessel:'M12 15 H43 L39 43 Q27 50 16 43 Z M15 23 Q21 18 28 23 T41 23',plant:'M27 48 V23 M27 35 Q9 35 11 15 Q28 15 27 35 M27 27 Q46 27 45 9 Q27 10 27 27',sun:'M27 9 V1 M27 53 V45 M8 27 H0 M54 27 H46 M8 8 L14 14 M40 40 L46 46 M8 46 L14 40 M40 14 L46 8 M39 27 A12 12 0 1 1 15 27 A12 12 0 1 1 39 27',group:'M8 49 V21 Q8 11 17 11 Q26 11 26 21 V49 M25 49 V21 Q25 11 34 11 Q43 11 43 21 V49 M3 49 H49',visitor:'M27 49 V23 M15 36 L27 23 L39 36 M20 10 A7 7 0 1 1 34 10 A7 7 0 1 1 20 10'};
const icon=n=>`<svg viewBox="0 0 54 54"><path d="${diagramIcons[n]}"/></svg>`;
function options(id){return `<option value="">Meaning?</option>`+meanings.map(w=>`<option value="${w}" ${guesses[id]===w?'selected':''}>${w}</option>`).join('');}
function selectHTML(id,prefix){return `<select aria-label="Meaning of alien mark ${id+1}" data-word="${id}" id="${prefix}-${id}" ${confirmed.has(id)?'disabled':''}>${options(id)}</select>`;}
function renderWords(){
$('#lexicon').innerHTML=words.map((_,i)=>`<label for="lex-${i}">${glyph(i,confirmed.has(i)?'confirmed':'')}${selectHTML(i,'lex')}</label>`).join('');
$('#sentence').innerHTML=chapters[chapter].sentence.map(i=>glyph(i,confirmed.has(i)?'confirmed':'')).join('');
$('#translation-slots').innerHTML=chapters[chapter].sentence.map(i=>`<label for="slot-${i}"><span class="slot-glyph">${glyph(i)}</span>${selectHTML(i,'slot')}</label>`).join('');
$('#lexicon-count').textContent=`${confirmed.size}/6`;
document.querySelectorAll('[data-word]').forEach(el=>el.addEventListener('change',()=>{guesses[Number(el.dataset.word)]=el.value;renderWords();feedback('Hypothesis updated. Test the inscription when you are ready.');}));
}
function feedback(text,kind=''){$('#feedback').textContent=text;$('#feedback').className=kind;}
function inspect(index){site=index;seen.add(index);const e=evidence[index];$('#site-label').textContent=`EVIDENCE 0${index+1} · ${e.title.toUpperCase()}`;$('#seen-count').textContent=`${seen.size} / 3 examined`;$('#observation').textContent=e.description;$('#field-note').textContent=e.note;$('#inscriptions').innerHTML=e.examples.map(ex=>`<div>${ex.marks.map(i=>glyph(i)).join('')}<span class="inscription-label">${ex.label}</span></div>`).join('');$('#evidence-drawing').innerHTML=(index===0?[icon('vessel'),'→',icon('plant')]:index===1?[icon('vessel'),'+',icon('sun'),'→',icon('plant')]:[icon('group'),'→',icon('vessel'),'→',icon('visitor')]).map(v=>v.length<2?`<span class="evidence-arrow">${v}</span>`:v).join('');document.querySelectorAll('[data-site]').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',i===index);});tab('evidence');window.dispatchEvent(new CustomEvent('archive-inspect',{detail:index}));}
function tab(name){['evidence','lexicon'].forEach(n=>{$(`#${n}-tab`).setAttribute('aria-selected',n===name);$(`#${n}-tab`).tabIndex=n===name?0:-1;$(`#${n}-panel`).hidden=n!==name;});}
function renderChapter(){const c=chapters[chapter];$('#chapter-label').textContent=`CHAPTER 0${chapter+1} / 03`;$('#progress-label').textContent=`${finished?3:chapter} of 3 inscriptions decoded`;$('#chapter-title').textContent=c.title;$('#chapter-description').textContent=c.description;$('#translation-context').textContent=c.context;$('#grammar-tag').textContent=chapter===2?'GIVER → RECIPIENT → GIFT → ACTION':'THE ACTION COMES LAST';document.querySelectorAll('.chapter-track i').forEach((e,i)=>{e.classList.toggle('done',i<chapter||finished);e.classList.toggle('current',i===chapter&&!finished);});$('#verify').innerHTML=finished?'Read the message ↗':'Test translation <span>↗</span>';renderWords();}
function verify(){if(finished){$('#ending').showModal();return;}if(solved){chapter++;solved=false;renderChapter();inspect(chapter);feedback('A new inscription is ready. Your confirmed words carry forward.');return;}const r=checkTranslation(chapter,guesses);if(!r.complete){feedback('Choose a meaning for every symbol before testing.','error');return;}if(!r.correct){feedback(`${r.matches} of ${r.total} meanings fit the evidence. Revisit the observations and revise your reading.`,'error');window.dispatchEvent(new CustomEvent('archive-response',{detail:'error'}));return;}
chapters[chapter].sentence.forEach(i=>confirmed.add(i));solved=true;renderWords();feedback(`Confirmed: “${chapters[chapter].translation}”`,'success');window.dispatchEvent(new CustomEvent('archive-response',{detail:chapter===2?'complete':'success'}));if(chapter===2){finished=true;document.body.classList.add('awakened');$('#signal-state').textContent='ARCHIVE AWAKE';$('#session-note').textContent='First contact established.';renderChapter();$('#ending').showModal();}else{$('#verify').innerHTML='Next inscription <span>↗</span>';$('#progress-label').textContent=`${chapter+1} of 3 inscriptions decoded`;document.querySelectorAll('.chapter-track i')[chapter].classList.add('done');}}
function restart(){chapter=0;site=0;solved=false;finished=false;guesses={};confirmed.clear();seen=new Set([0]);document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.body.classList.remove('awakened');$('#signal-state').textContent='ARCHIVE DORMANT';$('#session-note').textContent='Take your time. There is no countdown.';renderChapter();inspect(0);feedback('Observe the evidence, then choose a meaning beneath each symbol.');window.dispatchEvent(new CustomEvent('archive-response',{detail:'reset'}));}
$('#verify').addEventListener('click',verify);$('#hint').addEventListener('click',()=>feedback(chapters[chapter].hint));$('#reset').addEventListener('click',()=>{if(!chapter&&!Object.values(guesses).some(Boolean)){restart();return;}if(confirm('Start over and clear your translations?'))restart();});document.querySelectorAll('[data-site]').forEach(b=>b.addEventListener('click',()=>inspect(Number(b.dataset.site))));['evidence','lexicon'].forEach(n=>$(`#${n}-tab`).addEventListener('click',()=>tab(n)));$('.tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=$('#evidence-tab').getAttribute('aria-selected')==='true'?'lexicon':'evidence';tab(n);$(`#${n}-tab`).focus();}});$('#help').addEventListener('click',()=>$('#guide').showModal());document.querySelectorAll('.close,.close-guide').forEach(b=>b.addEventListener('click',()=>$('#guide').close()));$('.close-ending').addEventListener('click',()=>$('#ending').close());$('.replay').addEventListener('click',restart);renderChapter();inspect(0);
// Progressive enhancement: the regular game remains fully usable without WebMCP.
const toolLife=new AbortController();window.addEventListener('pagehide',()=>toolLife.abort());
if(document.modelContext?.registerTool){try {document.modelContext.registerTool({name:'inspect_archive_evidence',description:'Inspect one of the three evidence sites in The Silent Archive.',inputSchema:{type:'object',properties:{site:{type:'integer',minimum:1,maximum:3}},required:['site'],additionalProperties:false},execute:async({site:n})=>{if(!Number.isInteger(n)||n<1||n>3)throw Error('Choose a site from 1 to 3.');inspect(n-1);return {content:[{type:'text',text:JSON.stringify(evidence[n-1])}]};}}, {signal:toolLife.signal});document.modelContext.registerTool({name:'test_archive_translation',description:'Assign hypotheses to alien marks and test the current inscription. Uses the same game validation as the visible controls.',inputSchema:{type:'object',properties:{hypotheses:{type:'array',items:{type:'object',properties:{mark:{type:'integer',minimum:1,maximum:6},meaning:{type:'string',enum:meanings}},required:['mark','meaning'],additionalProperties:false}}},required:['hypotheses'],additionalProperties:false},execute:async({hypotheses})=>{if(!Array.isArray(hypotheses))throw Error('Hypotheses must be an array.');for(const h of hypotheses){if(!h||!Number.isInteger(h.mark)||h.mark<1||h.mark>6||!meanings.includes(h.meaning))throw Error('Invalid hypothesis.');}for(const h of hypotheses){if(!confirmed.has(h.mark-1))guesses[h.mark-1]=h.meaning;}renderWords();verify();return {content:[{type:'text',text:$('#feedback').textContent}]};}}, {signal:toolLife.signal});}catch(error){console.warn('Optional agent controls unavailable',error);}}
